//! Actual SELECT construction preserves native option ownership and nearby App state.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.attr(n,"id")==Some(id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
#[test]
fn range_contextual_fragment_actual_app_trusted_publication_keeps_paint_editor_and_links(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-range-contextual-fragment-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><html><head><style>body{margin:0;background:white}#paint{position:absolute;left:20px;top:20px;width:120px;height:32px;background:#114455}#paint.ready{background:#228844}#go{position:absolute;left:220px;top:20px;width:160px;height:32px}#menu{position:absolute;left:20px;top:80px;width:150px;height:30px}#newmenu{position:absolute;left:20px;top:130px;width:150px;height:30px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}</style></head><body><div id=paint>Indicator</div><select id=menu><optgroup id=group label=Group disabled><option value=a>A<hr id=separator><option id=second value=b selected>B</select><div id=mount></div><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><button id=go type=button>Construct select</button><div id=destination></div><script>
var mount=document.getElementById('mount'),watch=new MutationObserver(function(){});watch.observe(mount,{childList:true});document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'actual pointer';var r=document.createRange();r.selectNodeContents(mount);var fragment=r.createContextualFragment('<span id=fresh>Fragment text</span><!--comment-->tail'),first=fragment.firstChild,last=fragment.lastChild;if(fragment.ownerDocument!==document||fragment.nodeType!==11||first.parentNode!==fragment||document.getElementById('fresh')!==null||watch.takeRecords().length)throw 'detached producer';if(mount.appendChild(fragment)!==fragment||fragment.firstChild!==null||mount.firstChild!==first||mount.lastChild!==last||first.ownerDocument!==document||first.textContent!=='Fragment text'||r.startContainer!==mount||r.startOffset)throw 'fragment identity and draining';var records=watch.takeRecords();if(records.length!==1||records[0].target!==mount||records[0].addedNodes.length!==3||records[0].addedNodes[0]!==first||records[0].addedNodes[2]!==last||records[0].removedNodes.length)throw 'actual insertion record';if(document.getElementById('neighbor').value!=='edited neighbor')throw 'native neighbor';document.getElementById('paint').className='ready';document.title='Range fragment preserved';};
</script></body></html>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);
 let before=app.draw();assert_eq!(before.pixels[(app.content_top()+40)as usize*before.width+110],0x114455);
 let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let scroll=app.scroll;
 let rect=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);
 assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,"Range fragment preserved");let fresh=node(&app,"fresh");assert_eq!(app.document.attr(fresh,"id"),Some("fresh"));
 let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+40)as usize*painted.width+110],0x228844);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);assert_eq!(app.scroll,scroll);
}
